// Parses slcards.txt into src/lib/data/slTerms.ts.
//
// This emits **only the data that comes out of the source file** — id, term,
// definition, sections, hl. The mechanical layer (cost, stats, rarity, keywords,
// abilities) is applied in slCards.ts, which is hand-editable and is NOT
// regenerated. That split is deliberate: a generated file cannot hold hand-tuned
// balance, because the next run would erase it.
//
//   npm run cards
//
// The output must be byte-identical on every run and on every machine.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = join(root, 'slcards.txt');
const OUT = join(root, 'src/lib/data/slTerms.ts');

/** The HL section. Everything else is SL. */
const HL_SECTIONS = new Set(['C4.1']);

/**
 * Trailing tabs are everywhere in the source and carry no meaning — several
 * header lines are written as `A2.2\t\t\t\t…`, which would otherwise parse as a
 * term row with an empty definition.
 */
function rstrip(line) {
  return line.replace(/[\s ]+$/u, '');
}

function slug(term) {
  return term
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function parse(text) {
  const terms = [];
  const byId = new Map();
  const sectionCounts = new Map();
  let section = null;
  let rows = 0;

  for (const raw of text.split(/\r?\n/)) {
    const line = rstrip(raw);
    if (line === '') continue;

    const tab = line.indexOf('\t');
    if (tab === -1) {
      // A bare section code. One of them is written `C4.1:`.
      section = line.replace(/:$/, '').trim();
      continue;
    }

    const term = line.slice(0, tab).trim();
    const definition = rstrip(line.slice(tab + 1)).replace(/\t+/g, ' ').trim();
    if (term === '' || definition === '') continue;

    rows++;
    sectionCounts.set(section, (sectionCounts.get(section) ?? 0) + 1);

    // Ten terms appear under two sections each. The first definition wins; the
    // extra section code is recorded so a card can be filtered from either.
    const id = slug(term);
    const existing = byId.get(id);
    if (existing) {
      if (section && !existing.sections.includes(section)) existing.sections.push(section);
      if (section && HL_SECTIONS.has(section)) existing.hl = true;
      continue;
    }

    const entry = {
      id,
      term,
      definition,
      sections: section ? [section] : [],
      hl: section ? HL_SECTIONS.has(section) : false
    };
    byId.set(id, entry);
    terms.push(entry);
  }

  return { terms, rows, sectionCounts };
}

function quote(value) {
  return JSON.stringify(value);
}

function emit(terms) {
  const lines = terms.map((t) => {
    const parts = [
      `id: ${quote(t.id)}`,
      `term: ${quote(t.term)}`,
      `definition: ${quote(t.definition)}`,
      `sections: [${t.sections.map(quote).join(', ')}]`
    ];
    if (t.hl) parts.push('hl: true');
    return `  { ${parts.join(', ')} }`;
  });

  return `// GENERATED BY scripts/build-sl-cards.mjs — DO NOT EDIT BY HAND.
// Run \`npm run cards\` to regenerate from slcards.txt.
//
// Hand-tuning belongs in slCards.ts (statlines, abilities, OVERRIDES), which is
// never regenerated. Editing this file will be silently undone.

export interface SlTerm {
  /** Stable slug of the term. Collections and decks are keyed on it. */
  id: string;
  term: string;
  definition: string;
  /** Every syllabus section the term appeared under. */
  sections: string[];
  /** HL-only content. */
  hl?: boolean;
}

export const SL_TERMS: SlTerm[] = [
${lines.join(',\n')}
];
`;
}

const text = readFileSync(SOURCE, 'utf8');
const { terms, rows, sectionCounts } = parse(text);
writeFileSync(OUT, emit(terms), 'utf8');

const sections = [...sectionCounts.entries()].map(([s, n]) => `${s} ${n}`).join(' · ');
console.log(`${rows} rows, ${sectionCounts.size} sections, ${terms.length} unique cards`);
console.log(sections);
const hl = terms.filter((t) => t.hl).length;
console.log(`${hl} HL, ${terms.length - hl} SL`);
console.log(`→ ${OUT.replace(root + '/', '')}`);
